import sys
from collections import deque

def shortestDistance(N, M, X, Y, A):
    if A[0][0] == 0:
        return -1

    if X == 0 and Y == 0:
        return 0

    visited = [[False] * M for _ in range(N)]
    queue = deque()
    queue.append((0, 0, 0))
    visited[0][0] = True

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    while queue:
        r, c, dist = queue.popleft()

        if r == X and c == Y:
            return dist

        for dr, dc in directions:
            nr, nc = r + dr, c + dc

            if 0 <= nr < N and 0 <= nc < M:
                if not visited[nr][nc] and A[nr][nc] == 1:
                    visited[nr][nc] = True
                    queue.append((nr, nc, dist + 1))

    return -1

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        N = int(next(iterator))
        M = int(next(iterator))
        X = int(next(iterator))
        Y = int(next(iterator))

        A = []
        for _ in range(N):
            row = []
            for _ in range(M):
                row.append(int(next(iterator)))
            A.append(row)

        result = shortestDistance(N, M, X, Y, A)
        print(result)
    except StopIteration:
        pass

if __name__ == "__main__":
    main()
